import{_ as o,o as r,c as l,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-06-05 :: Ceph Developer Monthly part 2","description":"","frontmatter":{"title":"2019-06-05 :: Ceph Developer Monthly part 2","date":"2019-06-05T00:00:00.000Z","updated":"2019-06-07T00:00:00.000Z","tags":["Ceph","分布式存储","升级降级策略","测试方案","自动化测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-05_-_-_Ceph_Developer_Monthly_part_2.md","filePath":"posts/2019/2019-06-05_-_-_Ceph_Developer_Monthly_part_2.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-06-05_-_-_Ceph_Developer_Monthly_part_2.md"};function n(p,t,i,_,a,g){return r(),l("div",null,[...t[0]||(t[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： [请填写会议日期和时间] <strong>参会人员</strong>： [请填写参会人员名单] <strong>会议主题</strong>： Ceph 分布式存储系统功能标志、升级降级策略及测试方案讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、功能标志与升级降级策略</strong></p><ul><li><strong>功能标志</strong>： 讨论了在升级和降级过程中引入新的方法，如 RVD 特性用于滚动 OSD 上的客户端使用情况，并讨论了是否需要为类似功能添加计费机制。</li><li><strong>缺失的功能标志</strong>： 指出在 RW 方式中缺少一些功能标志，特别是 RDW 特性，需要重点关注。</li><li><strong>COS 守护进程版本</strong>： 强调了基于 COS 守护进程的版本信息对于确定基础版本的重要性。</li><li><strong>升级降级策略</strong>： 讨论了在升级过程中是否允许降级，以及如何处理不兼容的更新。提出了一种策略，即在特定版本系列中明确决定不支持从 5.4 版本降级。</li><li><strong>特殊版本发布</strong>： 提出在发布说明中明确指出某些特殊版本不支持降级，以避免用户误解。</li><li><strong>迁移路径</strong>： 讨论了在引入重大变更时，需要提供迁移路径，以便用户能够选择不访问某些功能。</li></ul><p><strong>二、测试方案</strong></p><ul><li><strong>测试自动化</strong>： 提出了使用 Jenkins 测试和编写脚本来自动检测代码中数值变化的建议，以便进行额外的审查。</li><li><strong>向后兼容性测试</strong>： 讨论了如何使用旧代码版本与新构建的代码进行交互，以测试向后兼容性。</li><li><strong>自动化测试套件</strong>： 讨论了构建一个自动化测试套件，以生成更具代表性的测试用例，并检测潜在的不兼容性。</li></ul><p><strong>三、行动计划</strong></p><ul><li>与 URI 合作，基于现有的 PGP 套件进行测试。</li><li>尝试为现有工作负载添加更多测试用例。</li><li>开发自动化工具，以检测代码中数值变化。</li><li>构建自动化测试套件，以生成更具代表性的测试用例。</li></ul><p><strong>四、其他事项</strong></p><ul><li>会议结束时，没有其他事项需要讨论。</li></ul><p><strong>会议总结</strong>：</p><p>本次会议围绕 Ceph 分布式存储系统的功能标志、升级降级策略及测试方案进行了深入讨论，明确了相关策略和行动计划，为后续开发工作提供了指导。会议中提到的关键点包括引入新的功能标志方法、处理升级和降级过程中的不兼容性、构建自动化测试套件等。</p><p><strong>改进点</strong>：</p><ol><li>增加了关于功能标志和升级降级策略的具体细节，如 RVD 特性、RDW 特性、COS 守护进程版本等。</li><li>强调了测试方案中的自动化测试和向后兼容性测试的重要性。</li><li>明确了后续行动计划中与 URI 的合作以及开发自动化工具的具体内容。</li></ol>',15)])])}const u=o(s,[["render",n]]);export{d as __pageData,u as default};
